package com.example.com.englishai.backend.presentation.rest.catalog;
import com.example.com.englishai.backend.application.admin.CatalogService; import com.example.com.englishai.backend.application.profile.ProfileImageStorage; import com.example.com.englishai.backend.infrastructure.persistence.repository.PredefinedAvatarJpaRepository; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*;
@RestController @RequestMapping("/api/v1/avatars") public class CatalogController { private final CatalogService service; private final PredefinedAvatarJpaRepository avatars; private final ProfileImageStorage storage; public CatalogController(CatalogService s,PredefinedAvatarJpaRepository a,ProfileImageStorage st){service=s;avatars=a;storage=st;} @GetMapping public List<AvatarResponse> avatars(){return service.publicAvatars().stream().map(e->new AvatarResponse(e.getAvatarKey(),e.getDisplayName(),"/api/v1/avatars/"+e.getAvatarKey()+"/image")).toList();} @GetMapping("/{key}/image") public ResponseEntity<byte[]> image(@PathVariable String key){var a=avatars.findByAvatarKey(key).orElseThrow(NoSuchElementException::new);byte[] bytes=storage.read(a.getAssetKey());String asset=a.getAssetKey().toLowerCase(Locale.ROOT);String type=asset.endsWith(".png")?"image/png":asset.endsWith(".webp")?"image/webp":"image/jpeg";return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).header(HttpHeaders.CACHE_CONTROL,"public, max-age=300").body(bytes);} public record AvatarResponse(String key,String displayName,String imageUrl){} }
